public enum ChimeraDesktopPlatform { case linuxGtk, linuxQt, windowsWin32, windowsModern, macOSAppKit, macOSSwiftUI, classic }
public enum ChimeraDesktopEventType { case windowCreate, windowClose, windowMove, windowResize, focusIn, focusOut, keyDown, keyUp, textInput, pointerMove, pointerDown, pointerUp, wheel, touchBegin, touchUpdate, touchEnd, gesture, dragBegin, dragUpdate, dragEnd, menuCommand, displayChange, themeChange, quit }
public struct ChimeraDesktopEvent { public let type: ChimeraDesktopEventType; public let timestampNs: UInt64; public let deviceId: String; public let windowId: String; public let x,y,dx,dy: Double; public let modifiers,buttons: UInt32; public let key,text: String }
public final class ChimeraEventRouter { private var handlers: [ChimeraDesktopEventType:(ChimeraDesktopEvent)->Void] = [:]; public init() {}; public func on(_ type: ChimeraDesktopEventType, _ handler:@escaping (ChimeraDesktopEvent)->Void){handlers[type]=handler}; public func dispatch(_ event: ChimeraDesktopEvent){handlers[event.type]?(event)} }
